        boolean readingConflict = fieldConflicts(base.reading(), current.reading(), request.reading(), true);
        if (readingConflict) conflictFields.add("reading");
        boolean noteConflict = fieldConflicts(base.note(), current.note(), request.note(), false);
        if (noteConflict) conflictFields.add("note");
        validateSelectionCoverage(selections.keySet(), conflictFields);
        String resolvedLocation = resolveFieldValue(locationConflict, selections.get("location"), base.location(), current.location(), request.location(), false);
        String resolvedReading = resolveFieldValue(readingConflict, selections.get("reading"), base.reading(), current.reading(), request.reading(), true);
        String resolvedNote = resolveFieldValue(noteConflict, selections.get("note"), base.note(), current.note(), request.note(), false);
