        }
        boolean conflict = sectionGroupConflicts(base, current, request.sectionNo(), request.lateralMm(), request.elevationMm());
        List<String> conflictFields = conflict ? List.of(SECTION_GROUP_FIELD) : List.of();
        validateSelectionCoverage(selections.keySet(), conflictFields);
        ObservationSnapshot merged;
        if (conflict) {
            merged = selections.get(SECTION_GROUP_FIELD) == FieldSelection.CANDIDATE
                    ? ObservationSnapshot.section(current.observationId(), current.version(), request.sectionNo(), request.lateralMm(), request.elevationMm(), false)
                    : current;
        } else if (sectionGroupEquals(request.sectionNo(), request.lateralMm(), request.elevationMm(), base)) {
            merged = current;
        } else {
            merged = ObservationSnapshot.section(current.observationId(), current.version(), request.sectionNo(), request.lateralMm(), request.elevationMm(), false);
        }
        return new MergePlan(conflictFields, merged);
    }
