```java
public static Fraction computeArea(List<Point> points, long waterLevelMm) {
    BigInteger h = BigInteger.valueOf(waterLevelMm);
    Fraction total = new Fraction(BigInteger.ZERO, BigInteger.ONE);
    for (int i = 0; i + 1 < points.size(); i++) {
        Point a = points.get(i);
        Point b = points.get(i + 1);
        BigInteger d0 = h.subtract(BigInteger.valueOf(a.elevationMm()));
        BigInteger d1 = h.subtract(BigInteger.valueOf(b.elevationMm()));
        BigInteger w = BigInteger.valueOf(b.lateralMm() - a.lateralMm());
        if (d0.signum() <= 0 && d1.signum() <= 0) {
            continue; // 整段在水下无正深度（含贴水），不积分；不外推
        }
        if (d0.signum() >= 0 && d1.signum() >= 0) {
            // 整段正深度：梯形
            total = total.add(new Fraction(d0.add(d1).multiply(w), BigInteger.TWO));
            continue;
        }
        // 跨水面：精确求交点，仅积分正深度三角形
        if (d0.signum() > 0) {
            // 交点距 a 为 w * d0 / (d0 - d1)，三角形面积 = d0^2 * w / (2 (d0 - d1))
            total = total.add(new Fraction(d0.multiply(d0).multiply(w),
                    BigInteger.TWO.multiply(d0.subtract(d1))));
        } else {
            total = total.add(new Fraction(d1.multiply(d1).multiply(w),
                    BigInteger.TWO.multiply(d1.subtract(d0))));
        }
    }
    return total;
}
