        createResult("req-i17", "result-1", "operator-a", 5,
                new String[][]{{"sec-a", "1"}, {"sec-b", "1"}})
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.areaExact").value("25/2"));
