package com.example.starter.observation;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

import java.util.Map;

/**
 * 冲突解决请求：在普通三方合并收到冲突后，提交字段完整候选值及对每个冲突字段（组）的人工选择。
 *
 * <p>FIELD 观测携带 location/reading/note 候选值，选择键为对应字段名；
 * SECTION 观测携带 sectionNo/lateralMm/elevationMm 完整版本组候选值，选择键为 sectionPoint。
 *
 * @param requestId              全局唯一请求标识（幂等去重键）
 * @param resolutionId           全局唯一解决记录标识
 * @param baseVersion            离线修改所基于的基线版本号（服务端据此重新读取基线重算冲突）
 * @param expectedCurrentVersion 客户端预期的解决前当前版本号，不匹配返回 409
 * @param location               观测地点候选完整值（FIELD）
 * @param reading                观测读数候选完整值，十进制字符串，最多三位小数（FIELD）
 * @param note                   观测备注候选完整值（FIELD）
 * @param sectionNo              断面号候选完整值（SECTION 版本组）
 * @param lateralMm              横向坐标候选完整值，整数毫米（SECTION 版本组）
 * @param elevationMm            高程候选完整值，整数毫米（SECTION 版本组）
 * @param selections             冲突字段（组）选择，键为字段名或 sectionPoint，值为 CURRENT 或 CANDIDATE；必须恰好覆盖本次仍冲突的字段（组）
 * @param operator               操作者标识
 */
public record ResolveConflictRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 128) String resolutionId,
        @NotNull @Min(1) Integer baseVersion,
        @NotNull @Min(1) Integer expectedCurrentVersion,
        @Size(max = 512) String location,
        @Pattern(regexp = "-?\\d+(\\.\\d{1,3})?", message = "reading must be a decimal string with at most 3 fraction digits")
        String reading,
        @Size(max = 1024) String note,
        @Size(max = 64) String sectionNo,
        Integer lateralMm,
        Integer elevationMm,
        @NotNull Map<String, String> selections,
        @NotBlank @Size(max = 128) String operator) {
}

package com.example.starter.observation;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.time.Instant;
import java.util.List;
import java.util.Optional;

/**
 * 冲突解决记录持久化：conflict_resolution 记录成功解决的完整上下文，不可变、永不更新。
 * 所有 SQL 使用参数化查询；冲突字段列表与选择映射以 JSON 原文存储。
 */
@Repository
public class ResolutionRepository {

    private static final TypeReference<List<String>> FIELD_LIST_TYPE = new TypeReference<>() {
    };
    private static final TypeReference<java.util.Map<String, String>> SELECTIONS_TYPE = new TypeReference<>() {
    };

    private final JdbcTemplate jdbcTemplate;
    private final ObjectMapper objectMapper;

    public ResolutionRepository(JdbcTemplate jdbcTemplate, ObjectMapper objectMapper) {
        this.jdbcTemplate = jdbcTemplate;
        this.objectMapper = objectMapper;
    }

    private static final String SELECT_COLUMNS =
            "resolution_id, observation_id, request_id, base_version, previous_version, "
                    + "new_version, candidate_location, candidate_reading, candidate_note, "
                    + "candidate_section_no, candidate_lateral_mm, candidate_elevation_mm, "
                    + "conflict_fields, field_selections, operator, content_changed, resolved_at_utc";

    /**
     * 插入一条不可变解决记录；resolutionId 主键或 (observationId, requestId) 唯一键冲突时抛出重复键异常。
     */
    public void insert(ResolutionRecord record) {
        jdbcTemplate.update(
                "INSERT INTO conflict_resolution (resolution_id, observation_id, request_id, "
                        + "base_version, previous_version, new_version, candidate_location, candidate_reading, "
                        + "candidate_note, candidate_section_no, candidate_lateral_mm, candidate_elevation_mm, "
                        + "conflict_fields, field_selections, operator, content_changed, "
                        + "resolved_at_utc, created_at) "
                        + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)",
                record.resolutionId(),
                record.observationId(),
                record.requestId(),
                record.baseVersion(),
                record.previousVersion(),
                record.newVersion(),
                record.candidateLocation(),
                record.candidateReading(),
                record.candidateNote(),
                record.candidateSectionNo(),
                record.candidateLateralMm(),
                record.candidateElevationMm(),
                writeJson(record.conflictFields()),
                record.fieldSelections(),
                record.operator(),
                record.contentChanged(),
                Timestamp.from(record.resolvedAtUtc()));
    }

    /**
     * 按全局唯一 resolutionId 查询解决记录；不存在时返回空。
     */
    public Optional<ResolutionRecord> findByResolutionId(String resolutionId) {
        return jdbcTemplate.query(
                        "SELECT " + SELECT_COLUMNS + " FROM conflict_resolution WHERE resolution_id = ?",
                        RESOLUTION_MAPPER, resolutionId)
                .stream().findFirst();
    }

    /**
     * 按 observationId 按解决时刻先后查询全部解决记录。
     */
    public List<ResolutionRecord> findByObservationId(String observationId) {
        return jdbcTemplate.query(
                "SELECT " + SELECT_COLUMNS + " FROM conflict_resolution WHERE observation_id = ? "
                        + "ORDER BY resolved_at_utc ASC, resolution_id ASC",
                RESOLUTION_MAPPER, observationId);
    }

    private String writeJson(Object value) {
        try {
            return objectMapper.writeValueAsString(value);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("failed to serialize resolution fields", e);
        }
    }

    private List<String> readFieldList(String json) {
        try {
            return objectMapper.readValue(json, FIELD_LIST_TYPE);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("failed to deserialize conflict fields", e);
        }
    }

    /**
     * 反序列化存储的选择 JSON；仅用于持久化层内部校验与比较，不参与记录不可变语义。
     */
    public java.util.Map<String, String> readSelections(String json) {
        try {
            return objectMapper.readValue(json, SELECTIONS_TYPE);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("failed to deserialize field selections", e);
        }
    }

    private final RowMapper<ResolutionRecord> RESOLUTION_MAPPER = (rs, rowNum) -> new ResolutionRecord(
            rs.getString("resolution_id"),
            rs.getString("observation_id"),
            rs.getString("request_id"),
            rs.getInt("base_version"),
            rs.getInt("previous_version"),
            rs.getInt("new_version"),
            rs.getString("candidate_location"),
            rs.getString("candidate_reading"),
            rs.getString("candidate_note"),
            rs.getString("candidate_section_no"),
            (Integer) rs.getObject("candidate_lateral_mm"),
            (Integer) rs.getObject("candidate_elevation_mm"),
            readFieldList(rs.getString("conflict_fields")),
            rs.getString("field_selections"),
            rs.getString("operator"),
            rs.getTimestamp("resolved_at_utc").toInstant(),
            rs.getBoolean("content_changed"));
}

package com.example.starter.observation;

import org.junit.jupiter.api.Test;

import java.math.BigInteger;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * 断面水域面积精确计算单元测试：跨水面交点精确求取、只积分正深度、两端之外不外推。
 */
class WaterAreaCalculatorTest {

    private static WaterAreaCalculator.Point point(long lateralMm, long elevationMm) {
        return new WaterAreaCalculator.Point(lateralMm, elevationMm);
    }

    private static void assertArea(List<WaterAreaCalculator.Point> points, long waterLevelMm,
                                   String numerator, String denominator) {
        WaterAreaCalculator.Fraction area = WaterAreaCalculator.computeArea(points, waterLevelMm);
        assertThat(area.numerator()).isEqualTo(new BigInteger(numerator));
        assertThat(area.denominator()).isEqualTo(new BigInteger(denominator));
    }

    @Test
    void syntheticCrossingSegmentYieldsHalfTriangle() {
        // 合成场景：横向 0 与 10 毫米、高程 0 与 10 毫米、水面 5 毫米，只有前半三角形有水
        assertArea(List.of(point(0, 0), point(10, 10)), 5, "25", "2");
    }

    @Test
    void fullySubmergedSegmentYieldsTrapezoid() {
        // 整段正深度：梯形 (5+5)*10/2 = 50，不向两端之外外推
        assertArea(List.of(point(0, 0), point(10, 0)), 5, "50", "1");
        // 变深梯形：(3+5)*10/2 = 40
        assertArea(List.of(point(0, 2), point(10, 0)), 5, "40", "1");
    }

    @Test
    void fullyDrySegmentYieldsZero() {
        assertArea(List.of(point(0, 10), point(10, 10)), 5, "0", "1");
        // 贴水（深度为 0）不产生面积
        assertArea(List.of(point(0, 5), point(10, 5)), 5, "0", "1");
    }

    @Test
    void risingCrossingIntegratesOnlyPositiveSide() {
        // 深度 (-5, 5)：仅右侧三角形 25/2，负深度不抵消
        assertArea(List.of(point(0, 10), point(10, 0)), 5, "25", "2");
    }

    @Test
    void multiSegmentWithPartialWaterSumsPositiveParts() {
        // V 形断面：两段各贡献 25/2，合计 25
        assertArea(List.of(point(0, 0), point(10, 10), point(20, 0)), 5, "25", "1");
    }

    @Test
    void noExtrapolationBeyondSectionEnds() {
        // 两端点之外不外推：水下段仅覆盖 [0,10]，端点外水面不计
        assertArea(List.of(point(0, 0), point(10, 0)), 5, "50", "1");
        // 中间有水、两端贴水：仅中间三角形
        assertArea(List.of(point(0, 5), point(10, 0), point(20, 5)), 5, "25", "1");
    }

    @Test
    void zeroDepthEndpointFormsDegenerateTrapezoid() {
        // 深度 (0, 5)：直角三角形 (0+5)*10/2 = 25
        assertArea(List.of(point(0, 5), point(10, 0)), 5, "25", "1");
    }

    @Test
    void exactFractionForAsymmetricCrossing() {
        // 深度 (1, -2)，宽 3：交点在 1/3 处，三角形面积 = 1*1*3/(2*3) = 1/2
        assertArea(List.of(point(0, 0), point(3, 3)), 1, "1", "2");
    }

    @Test
    void negativeLateralCoordinatesSupported() {
        assertArea(List.of(point(-10, 0), point(0, 0)), 5, "50", "1");
    }

    @Test
    void fractionIsReduced() {
        // (2+2)*3/2 = 6，约分为 6/1
        assertArea(List.of(point(0, 0), point(3, 0)), 2, "6", "1");
    }
}
